class Order {
  private String orderId;
  private User user;
  private List<OrderItem> items; // snapshot of product+price
  private OrderStatus status;   // PLACED, PROCESSING, SHIPPED, DELIVERED
  private Payment payment;
  private Address shippingAddress;
}

public enum OrderStatus {
  PLACED, CONFIRMED, PROCESSING, SHIPPED, DELIVERED, CANCELLED, RETURNED;
}

public class Order {
  private OrderStatus status = OrderStatus.PLACED;

  public void confirm() {
    if (status != OrderStatus.PLACED)
      throw new InvalidStateException("Cannot confirm " + status);
    this.status = OrderStatus.CONFIRMED;
    // notify warehouse
  }

  public void cancel() {
    if (!EnumSet.of(PLACED, CONFIRMED).contains(status))
      throw new InvalidStateException("Cannot cancel " + status);
    this.status = OrderStatus.CANCELLED;
    // process refund
  }
}

public class Inventory {
  private String productId;
  private int availableCount;
  private int reservedCount;  // reserved but not yet shipped

  public synchronized boolean reserve(int quantity) {
    if (availableCount >= quantity) {
      availableCount -= quantity;
      reservedCount += quantity;
      return true; // reservation successful
    }
    return false; // out of stock
  }

  public synchronized void release(int quantity) {
    // called if order is cancelled
    reservedCount -= quantity;
    availableCount += quantity;
  }
}

interface PaymentProcessor {
  PaymentResult process(Payment payment);
  PaymentResult refund(Payment payment, BigDecimal amount);
}

