class Payment {
  private String paymentId;
  private BigDecimal amount;
  private PaymentStatus status; // PENDING, SUCCESS, FAILED, REFUNDED
  private PaymentMethod method;
  private String transactionId; // external gateway transaction ID
}

class Review {
  private String reviewId;
  private String productId;
  private String userId;
  private int rating;  // 1-5
  private String reviewText;
  private boolean verifiedPurchase; // only for confirmed buyers
  private LocalDateTime createdAt;
}

class Product {
  // Cached average — updated when reviews change
  private double averageRating;
  private int reviewCount;

  void updateRating(double newRating) {
    averageRating = (averageRating * reviewCount + newRating)
                   / (reviewCount + 1);
    reviewCount++;
  }
}
